B.aoA=new A.S("\u041a\u0432\u0438\u0442\u043e\u043a \u0431\u0435\u0440\u0451\u0442 \u043f\u0440\u043e\u0446\u0435\u043d\u0442 \u0441 \u043f\u043b\u0430\u0442\u0435\u0436\u0435\u0439?","\u041d\u0435\u0442. \u041a\u0432\u0438\u0442\u043e\u043a \u043d\u0435 \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442 \u043e\u043f\u043b\u0430\u0442\u0443 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u0439 \u0438 \u043d\u0435 \u0432\u0438\u0434\u0438\u0442 \u0432\u0430\u0448\u0438\u0445 \u0434\u0435\u043d\u0435\u0433: \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u0432 \u0431\u0430\u043d\u043a\u0435 \u0438\u043b\u0438 \u043d\u0430 \u043f\u043e\u0447\u0442\u0435, \u043a\u0430\u043a \u043e\u0431\u044b\u0447\u043d\u043e. \u041a\u0432\u0438\u0442\u043e\u043a \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u044e. \u0421\u0430\u043c \u043e\u043d \u0441\u0442\u043e\u0438\u0442 \u0442\u0430\u043a: \u043f\u0435\u0440\u0432\u044b\u0435 2 \u043c\u0435\u0441\u044f\u0446\u0430 \u0441 \u043f\u0435\u0440\u0432\u043e\u0439 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u0438 - \u0431\u0435\u0441\u043f\u043b\u0430\u0442\u043d\u043e, \u043f\u043e\u0442\u043e\u043c 490 \u20bd \u0437\u0430 \u0433\u043e\u0434, \u043e\u0434\u0438\u043d \u0440\u0430\u0437, \u0431\u0435\u0437 \u0430\u0432\u0442\u043e\u043f\u0440\u043e\u0434\u043b\u0435\u043d\u0438\u044f. \u0414\u043b\u044f \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f: \u0441\u043e\u0441\u0442\u0430\u0432\u0438\u0442\u044c \u043f\u0440\u0435\u0442\u0435\u043d\u0437\u0438\u044e \u0443 \u044e\u0440\u0438\u0441\u0442\u0430 \u043f\u043e \u0416\u041a\u0425 - \u043e\u0442 4 000 \u20bd.")
B.aoD=new A.S("\u041a\u0430\u043a\u043e\u0439 \u0438\u0441\u043a\u0443\u0441\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0438\u043d\u0442\u0435\u043b\u043b\u0435\u043a\u0442 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u0438?","\u041d\u0438\u043a\u0430\u043a\u043e\u0439 \u0438\u0437 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0430. \u0422\u0435\u043a\u0441\u0442 \u0441 \u0444\u043e\u0442\u043e \u0447\u0438\u0442\u0430\u0435\u0442 \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u0430\u044f \u043f\u0440\u043e\u0433\u0440\u0430\u043c\u043c\u0430 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u044f Tesseract - \u043e\u043d\u0430 \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u043f\u0440\u044f\u043c\u043e \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435. \u041f\u0440\u043e\u0432\u0435\u0440\u044f\u044e\u0442 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u044e \u043f\u0440\u0430\u0432\u0438\u043b\u0430: \u043e\u0431\u044a\u0451\u043c \xd7 \u0442\u0430\u0440\u0438\u0444, \u0438\u0442\u043e\u0433, \u043f\u043b\u043e\u0449\u0430\u0434\u044c, \u043d\u043e\u0440\u043c\u044b \u0437\u0430\u043a\u043e\u043d\u0430. \u041f\u043e\u044d\u0442\u043e\u043c\u0443 \u0443 \u043a\u0430\u0436\u0434\u043e\u0439 \u043d\u0430\u0445\u043e\u0434\u043a\u0438 \u0435\u0441\u0442\u044c \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u0435 \xab\u041f\u043e\u0447\u0435\u043c\u0443 \u0442\u0430\u043a \u0440\u0435\u0448\u0438\u043b\u0438\xbb, \u0438 \u0435\u0433\u043e \u043c\u043e\u0436\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0441\u0430\u043c\u043e\u043c\u0443.")
B.ao8=new A.S("\u041a\u0443\u0434\u0430 \u0443\u0445\u043e\u0434\u044f\u0442 \u043c\u043e\u0438 \u0444\u043e\u0442\u043e \u0438 \u0434\u0430\u043d\u043d\u044b\u0435?","\u041d\u0438\u043a\u0443\u0434\u0430. \u041a\u0432\u0438\u0442\u043e\u043a \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u0431\u0435\u0437 \u0438\u043d\u0442\u0435\u0440\u043d\u0435\u0442\u0430: \u0444\u043e\u0442\u043e \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0451\u0442\u0441\u044f \u043d\u0430 \u0442\u0435\u043b\u0435\u0444\u043e\u043d\u0435, \u0438\u0441\u0442\u043e\u0440\u0438\u044f \u0445\u0440\u0430\u043d\u0438\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0434\u0435\u0441\u044c. \u0424\u0418\u041e, \u0430\u0434\u0440\u0435\u0441 \u0438 \u043b\u0438\u0446\u0435\u0432\u043e\u0439 \u0441\u0447\u0451\u0442 \u043d\u0435 \u0441\u043e\u0445\u0440\u0430\u043d\u044f\u044e\u0442\u0441\u044f.")
B.ao7=new A.S("\u041a\u0430\u043a \u043d\u0435 \u043f\u043e\u0442\u0435\u0440\u044f\u0442\u044c \u0438\u0441\u0442\u043e\u0440\u0438\u044e?","\u041d\u0430 Android 10 \u0438 \u043d\u043e\u0432\u0435\u0435 \u041a\u0432\u0438\u0442\u043e\u043a \u0441\u0430\u043c \u043a\u043b\u0430\u0434\u0451\u0442 \u043a\u043e\u043f\u0438\u044e \u0432 \xab\u0417\u0430\u0433\u0440\u0443\u0437\u043a\u0438 \u2192 \u041a\u0432\u0438\u0442\u043e\u043a\xbb. \u041f\u043e\u0441\u043b\u0435 \u043f\u0435\u0440\u0435\u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0438 - \xab\u041c\u043e\u044f \u0438\u0441\u0442\u043e\u0440\u0438\u044f\xbb \u2192 \xab\u0412\u043e\u0441\u0441\u0442\u0430\u043d\u043e\u0432\u0438\u0442\u044c \u0438\u0437 \u043a\u043e\u043f\u0438\u0438\xbb.")
B.anV=new A.S("\u041a\u0432\u0438\u0442\u043e\u043a \u043e\u0448\u0438\u0431\u0441\u044f \u0432 \u0441\u0442\u0440\u043e\u043a\u0435. \u0427\u0442\u043e \u0434\u0435\u043b\u0430\u0442\u044c?","\u041d\u0430\u0436\u043c\u0438\u0442\u0435 \u043d\u0430 \u0441\u0442\u0440\u043e\u043a\u0443 \u0438 \u0438\u0441\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u043f\u043e \u0444\u043e\u0442\u043e. \u041d\u0430\u0445\u043e\u0434\u043a\u0438 \u043f\u0435\u0440\u0435\u0441\u0447\u0438\u0442\u0430\u044e\u0442\u0441\u044f \u0441\u0440\u0430\u0437\u0443.")
B.aov=new A.S("\u041d\u0430\u0445\u043e\u0434\u043a\u0430 \u0437\u043d\u0430\u0447\u0438\u0442, \u0447\u0442\u043e \u043c\u0435\u043d\u044f \u043e\u0431\u0441\u0447\u0438\u0442\u0430\u043b\u0438?","\u041d\u0435\u0442. \u042d\u0442\u043e \u043f\u043e\u0432\u043e\u0434 \u0441\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u043e\u0440\u0433\u0430\u043d\u0438\u0437\u0430\u0446\u0438\u044e. \u041e\u0448\u0438\u0431\u043a\u0430 \u043c\u043e\u0436\u0435\u0442 \u0431\u044b\u0442\u044c \u0438 \u0432 \u0440\u0430\u0441\u043f\u043e\u0437\u043d\u0430\u0432\u0430\u043d\u0438\u0438, \u0438 \u0437\u0430\u043a\u043e\u043d\u043d\u0430\u044f \u043f\u0440\u0438\u0447\u0438\u043d\u0430 - \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440, \u043f\u0435\u0440\u0435\u0440\u0430\u0441\u0447\u0451\u0442 \u0437\u0430 \u043f\u0440\u043e\u0448\u043b\u044b\u0435 \u043c\u0435\u0441\u044f\u0446\u044b.")
B.aor=new A.S("\u041f\u043e\u0447\u0435\u043c\u0443 \u0423\u041a \u043d\u0435 \u043f\u0440\u0438\u043d\u044f\u043b\u0430 \u043c\u043e\u0451 \u043f\u0438\u0441\u044c\u043c\u043e?","\u041e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u044e\u0442, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u0432 \u043d\u0451\u043c \u0435\u0441\u0442\u044c \u0444\u0430\u043c\u0438\u043b\u0438\u044f, \u0438\u043c\u044f, \u043e\u0442\u0447\u0435\u0441\u0442\u0432\u043e, \u0430\u0434\u0440\u0435\u0441, \u0442\u0435\u043b\u0435\u0444\u043e\u043d, \u043f\u043e\u0434\u043f\u0438\u0441\u044c \u0438 \u0434\u0430\u0442\u0430, \u0430 \u0432 \u043f\u0438\u0441\u044c\u043c\u0435 - \u0435\u0449\u0451 \u0438 \u043f\u043e\u0447\u0442\u0430 \u0434\u043b\u044f \u043e\u0442\u0432\u0435\u0442\u0430. \u0423\u043f\u0440\u0430\u0432\u043b\u044f\u044e\u0449\u0438\u0435 \u043a\u043e\u043c\u043f\u0430\u043d\u0438\u0438 \u0441\u0441\u044b\u043b\u0430\u044e\u0442\u0441\u044f \u043d\u0430 \u0437\u0430\u043a\u043e\u043d \u043e\u0431 \u043e\u0431\u0440\u0430\u0449\u0435\u043d\u0438\u044f\u0445 \u0433\u0440\u0430\u0436\u0434\u0430\u043d (\u2116 59-\u0424\u0417) \u0438 \u0431\u0435\u0437 \u044d\u0442\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 \u043d\u0435 \u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u044e\u0442. \u0414\u0430\u0436\u0435 \u0435\u0441\u043b\u0438 \u0440\u0430\u043d\u044c\u0448\u0435 \u0432\u0430\u043c \u043e\u0442\u0432\u0435\u0447\u0430\u043b\u0438 \u043f\u043e \u043f\u043e\u0447\u0442\u0435. \u0417\u0430\u043f\u043e\u043b\u043d\u0438\u0442\u0435 \xab\u0412\u0430\u0448\u0438 \u0434\u0430\u043d\u043d\u044b\u0435\xbb \u043d\u0430 \u044d\u043a\u0440\u0430\u043d\u0435 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u044f - \u041a\u0432\u0438\u0442\u043e\u043a \u0432\u043f\u0438\u0448\u0435\u0442 \u0438\u0445 \u0432 \u0442\u0435\u043a\u0441\u0442 \u0441\u0430\u043c \u0438 \u043d\u0430\u043f\u043e\u043c\u043d\u0438\u0442, \u0435\u0441\u043b\u0438 \u0447\u0435\u0433\u043e-\u0442\u043e \u043d\u0435 \u0445\u0432\u0430\u0442\u0430\u0435\u0442.")
B.aoJ=new A.S("\u042f \u0441\u043d\u0438\u043c\u0430\u044e \u043a\u0432\u0430\u0440\u0442\u0438\u0440\u0443 - \u043c\u043e\u0436\u043d\u043e \u043f\u043e\u0434\u0430\u0442\u044c \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0435?","\u0414\u0430, \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0443 \u043d\u0430\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u043c\u043e\u0436\u0435\u0442 \u043f\u043e\u043f\u0440\u043e\u0441\u0438\u0442\u044c \u0438 \u0442\u043e\u0442, \u043a\u0442\u043e \u0436\u0438\u0432\u0451\u0442 \u043f\u043e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0443 \u0441 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u043e\u043c (\u043f. 2 \u041f\u0440\u0430\u0432\u0438\u043b \u2116 354). \u0412 \xab\u0412\u0430\u0448\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445\xbb \u0432\u044b\u0431\u0435\u0440\u0438\u0442\u0435 \xab\u0421\u043d\u0438\u043c\u0430\u044e \u0443 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0430\xbb - \u041a\u0432\u0438\u0442\u043e\u043a \u0432\u043f\u0438\u0448\u0435\u0442 \u044d\u0442\u043e \u0432 \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u0438 \u0434\u043e\u0431\u0430\u0432\u0438\u0442 \u043a\u043e\u043f\u0438\u044e \u0434\u043e\u0433\u043e\u0432\u043e\u0440\u0430 \u043d\u0430\u0439\u043c\u0430 \u0432 \u043f\u0440\u0438\u043b\u043e\u0436\u0435\u043d\u0438\u0435. \u0428\u0442\u0440\u0430\u0444 50% \u0432\u044b\u043f\u043b\u0430\u0447\u0438\u0432\u0430\u044e\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a\u0443 \u0438\u043b\u0438 \u043d\u0430\u043d\u0438\u043c\u0430\u0442\u0435\u043b\u044e \u0433\u043e\u0441\u0443\u0434\u0430\u0440\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0438\u043b\u0438 \u043c\u0443\u043d\u0438\u0446\u0438\u043f\u0430\u043b\u044c\u043d\u043e\u0433\u043e \u0436\u0438\u043b\u044c\u044f (\u0447. 6 \u0441\u0442. 157 \u0416\u041a \u0420\u0424) - \u044d\u0442\u043e \u0437\u0430\u044f\u0432\u043b\u0435\u043d\u0438\u0435 \u043f\u043e\u0434\u0430\u0451\u0442 \u0441\u043e\u0431\u0441\u0442\u0432\u0435\u043d\u043d\u0438\u043a.")
B.aou=new A.S("\u041a\u0443\u0434\u0430 \u0436\u0430\u043b\u043e\u0432\u0430\u0442\u044c\u0441\u044f, \u0435\u0441\u043b\u0438 \u0423\u041a \u043d\u0435 \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442?","\u0412 \u0436\u0438\u043b\u0438\u0449\u043d\u0443\u044e \u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044e - \u0447\u0435\u0440\u0435\u0437 \u0413\u0418\u0421 \u0416\u041a\u0425 \u0438\u043b\u0438 \u0413\u043e\u0441\u0443\u0441\u043b\u0443\u0433\u0438. \u041d\u0430 \u0433\u043b\u0430\u0432\u043d\u043e\u0439 - \xab\u0416\u0430\u043b\u043e\u0431\u0430 \u0432 \u0436\u0438\u043b\u0438\u043d\u0441\u043f\u0435\u043a\u0446\u0438\u044e\xbb, \u0442\u0430\u043c \u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u0442\u0435\u043a\u0441\u0442.")
B.aoL=new A.S("\u041f\u043e\u0447\u0435\u043c\u0443 \u043a\u0432\u0438\u0442\u0430\u043d\u0446\u0438\u044f \u043d\u0435 \u043f\u0440\u043e\u0447\u0438\u0442\u0430\u043b\u0430\u0441\u044c?","\u0427\u0430\u0449\u0435 \u0432\u0441\u0435\u0433\u043e \u0444\u043e\u0442\u043e \u0441\u0436\u0430\u0442\u043e \u043c\u0435\u0441\u0441\u0435\u043d\u0434\u0436\u0435\u0440\u043e\u043c, \u0442\u0451\u043c\u043d\u043e\u0435 \u0438\u043b\u0438 \u0441\u043d\u044f\u0442\u043e \u043f\u043e\u0434 \u0443\u0433\u043b\u043e\u043c. \u0421\u043d\u0438\u043c\u0438\u0442\u0435 \u043a\u0430\u043c\u0435\u0440\u043e\u0439 \u041a\u0432\u0438\u0442\u043a\u0430 \u0438\u043b\u0438 \u043e\u0442\u043f\u0440\u0430\u0432\u044c\u0442\u0435 \u0444\u0430\u0439\u043b\u043e\u043c PDF.")
B.ao_=new A.S("\u042d\u0442\u043e \u044e\u0440\u0438\u0434\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043a\u043e\u043d\u0441\u0443\u043b\u044c\u0442\u0430\u0446\u0438\u044f?","\u041d\u0435\u0442. \u041a\u0432\u0438\u0442\u043e\u043a \u0441\u0432\u0435\u0440\u044f\u0435\u0442 \u0430\u0440\u0438\u0444\u043c\u0435\u0442\u0438\u043a\u0443 \u0438 \u0433\u043e\u0442\u043e\u0432\u0438\u0442 \u0442\u0435\u043a\u0441\u0442 \u0437\u0430\u043f\u0440\u043e\u0441\u0430. \u0417\u0430 \u0434\u0430\u043d\u043d\u044b\u0435, \u043a\u043e\u0442\u043e\u0440\u044b\u0435 \u0432\u044b \u0432\u0432\u0435\u043b\u0438 \u0438\u043b\u0438 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u043b\u0438, \u043e\u0442\u0432\u0435\u0447\u0430\u0435\u0442\u0435 \u0432\u044b.")
B.a3W=s([B.aoA,B.aoD,B.ao8,B.ao7,B.anV,B.aov,B.aor,B.aoJ,B.aou,B.aoL,B.ao_],t.Wy)
